bootModule(['module' => 'finance', 'page' => 'reports', 'pageTitle' => 'Finance Reports - ARMIS', 'moduleName' => 'Finance', 'moduleIcon' => 'calculator']);
$manager = new FinanceManager((string) $_SESSION['user_id']); $summary = $manager->getDashboardSummary(); $budgets = $manager->getBudgets(); $expenditures = $manager->getExpenditures();
if (($_GET['export'] ?? '') === 'csv') { header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="finance-report-' . date('Y-m-d') . '.csv"'); $output = fopen('php://output', 'w'); fputcsv($output, ['Finance Report', 'Amount']); fputcsv($output, ['Budget', $summary['total_budget']]); fputcsv($output, ['Approved/Paid Expenditure', $summary['spent']]); fputcsv($output, ['Remaining', $summary['remaining']]); fclose($output); exit; }
